rep('''        K.check(set(old[PKG + c_]) <= set(new[PKG + c_]), "C every 0.2.3 %s member is still there (only additions)" % c_)''',
    '''        K.check(set(old[PKG + c_]) <= set(new[PKG + c_]), "C every 0.2.4 %s member is still there (only additions)" % c_)''')
